//! Markdown → RTF for the "View" mode.
//!
//! Security: RichEdit only ever receives RTF generated by this module.
//! All document text is escaped (`\`, `{`, `}` and all non-ASCII → `\uN?`), so
//! .md content cannot inject RTF control words (\object, \field, etc.).
//! No RTF from a file or the clipboard is ever loaded into RichEdit.
//!
//! Internal "markers" are Private Use Area characters inserted as hidden text (\v):
//! link start/end, heading anchors, image slots. Link positions are later
//! located by these markers in the control's text. The same characters coming from the document
//! itself are replaced with U+FFFD so they cannot be forged.

use std::collections::HashMap;
use std::fmt::Write as _;

use pulldown_cmark::{Alignment, BlockQuoteKind, CodeBlockKind, Event, HeadingLevel, LinkType, Options, Parser, Tag, TagEnd};

use crate::highlight::Kind;
use crate::html::{self, Tok};
use crate::theme::{self, Theme};

pub const LINK_START: u32 = 0xE000;
pub const MAX_LINKS: usize = 0x800;
pub const ANCHOR: u32 = 0xE800;
pub const MAX_ANCHORS: usize = 0x400;
pub const IMAGE: u32 = 0xEC00;
pub const MAX_IMAGES: usize = 0x800;
pub const LINK_END: u32 = 0xF8FE;
pub const IMAGE_END: u32 = 0xF8FD;

pub fn md_options() -> Options {
    Options::ENABLE_TABLES
        | Options::ENABLE_FOOTNOTES
        | Options::ENABLE_STRIKETHROUGH
        | Options::ENABLE_TASKLISTS
        | Options::ENABLE_MATH
        | Options::ENABLE_GFM
        | Options::ENABLE_DEFINITION_LIST
        | Options::ENABLE_YAML_STYLE_METADATA_BLOCKS
}

#[derive(Debug, Clone)]
pub struct ImageReq {
    pub id: usize,
    pub src: String,
    pub width: Option<u32>,
    pub height: Option<u32>,
}

#[derive(Debug, Clone)]
pub struct LinkInfo {
    pub url: String,
    pub text: String,
}

#[derive(Debug, Default)]
pub struct Rendered {
    pub rtf: String,
    pub links: Vec<LinkInfo>,
    pub anchors: Vec<String>,
    pub images: Vec<ImageReq>,
    /// End of the RTF header (fonts, colors) — start of the body.
    pub body_start: usize,
    /// Starts of body chunks for progressive loading: (offset in `rtf`, offset in the source).
    /// The first chunk starts at `body_start`. Boundaries are only between ordinary top-level
    /// paragraphs (not inside tables/quotes/groups), so each chunk is self-contained RTF.
    pub splits: Vec<(usize, usize)>,
}

impl Rendered {
    /// End of the body (before the document's closing brace).
    pub fn body_end(&self) -> usize {
        self.rtf.trim_end().len() - 1
    }

    pub fn chunk_count(&self) -> usize {
        self.splits.len()
    }

    /// Chunk `i` as a standalone RTF document (header + chunk body).
    ///
    /// On a full text replace (EM_SETTEXTEX) RichEdit "eats" the last \par — it
    /// merges with the document's final paragraph. So the first loaded chunk (`first`)
    /// gets an empty tiny paragraph appended: that one is eaten, and the real paragraph stays intact.
    /// On insertion via TOM (at the start or the end) \par is not eaten — no tail is needed.
    /// Covered by the chunked_load_equals_full_load test.
    pub fn chunk_rtf(&self, i: usize, first: bool) -> String {
        let a = self.splits[i].0;
        let last = i + 1 >= self.splits.len();
        let b = self.splits.get(i + 1).map(|s| s.0).unwrap_or_else(|| self.body_end());
        let mut s = String::with_capacity(self.body_start + (b - a) + 40);
        s.push_str(&self.rtf[..self.body_start]);
        let body = &self.rtf[a..b];
        // The last chunk ends with that very tiny paragraph of the document; on insertion
        // via TOM it would remain as an extra line — the final paragraph already exists.
        let body = if last && !first { body.strip_suffix(CHUNK_TAIL).unwrap_or(body) } else { body };
        s.push_str(body);
        if !last && first {
            s.push_str(CHUNK_TAIL);
        }
        s.push('}');
        s
    }
}

const CHUNK_TAIL: &str = "\\pard\\plain\\sb0\\sa0\\fs2\\par\n";

/// Where to append the next chunk: `len` — the control's text length (EM_GETTEXTLENGTHEX).
pub fn chunk_append_pos(len: i32) -> i32 {
    len.max(0)
}

/// Approximate RTF chunk size for progressive loading (≈ 20 ms of parsing in RichEdit).
const CHUNK_BYTES: usize = 40 * 1024;

pub struct RenderOpts<'a> {
    pub theme: &'a Theme,
    /// Text column width in twips (1/1440 inch).
    pub width_twips: i32,
    /// Document folder — for marking blocked links visibly in advance.
    pub base_dir: Option<&'a std::path::Path>,
    /// Padding above the document and empty space after the end (the last paragraph can be
    /// scrolled up to the middle of the screen). Done with paragraphs, not RichEdit margins: on scrolling
    /// the control's margins are not repainted and stripes of other text remained in them.
    pub top_pad_twips: i32,
    pub tail_twips: i32,
}

impl<'a> RenderOpts<'a> {
    pub fn new(theme: &'a Theme, width_twips: i32) -> Self {
        RenderOpts { theme, width_twips, base_dir: None, top_pad_twips: 0, tail_twips: 0 }
    }
}

