    /// "Bombs": deep nesting, thousands of opening brackets/tags, huge tables.
    /// Rendering and parsing for the editor must finish in reasonable time and produce
    /// balanced RTF.
    #[test]
    fn pathological_inputs_are_fast_and_balanced() {
        let mut table = "| a ".repeat(300);
        table.push_str("|\n");
        table.push_str(&"| --- ".repeat(300));
        table.push_str("|\n");
        let cases: Vec<(&str, String)> = vec![
            ("quotes x5000", format!("{}x", "> ".repeat(5000))),
            ("lists x3000", (0..3000).map(|i| format!("{}- x\n", "  ".repeat(i))).collect()),
            ("asterisks", "*".repeat(60_000)),
            ("brackets", "[".repeat(60_000)),
            ("backticks", "`".repeat(60_000)),
            ("<b> tags", format!("{}x", "<b>".repeat(30_000))),
            ("emphases", format!("{}x{}", "*a ".repeat(20_000), "*".repeat(20_000))),
            ("table with 300 columns", table),
            ("images x5000", "![](a.png)".repeat(5000)),
            ("links x5000", "[x](https://a.b)".repeat(5000)),
            ("html comments", "<!--".repeat(30_000)),
            ("entities", "&#x".repeat(40_000)),
            // — scenarios from the audit —
            ("address + 300000 parens", format!("https://a.b{}", ")".repeat(300_000))),
            ("candidates xwww.", "xwww.".repeat(200_000)),
            ("unclosed tags <a <a", format!("<div {}", "<a ".repeat(100_000))),
            ("ampersands in HTML", format!("<div>\n{}", "&".repeat(1_000_000))),
            ("<b> x300000", format!("{}x", "<b>".repeat(300_000))),
            ("<b> and </i>", format!("{}{}", "<b>".repeat(50_000), "</i>".repeat(50_000))),
            ("unclosed <a href>", "<a href=\"https://evil.example\">\n\nвесь документ\n\nещё".to_string()),
            ("megabyte definition ×3000 images", format!("[x]: https://e.com/{}\n\n{}", "A".repeat(2_000_000), "![a][x]".repeat(3000))),
            ("megabyte definition ×200000 links", format!("[x]: https://e.com/{}\n\n{}", "A".repeat(2_000_000), "[a][x]".repeat(200_000))),
            ("data: 1 MB ×100", format!("![a](data:image/png;base64,{})\n", "A".repeat(1_000_000)).repeat(100)),
            ("table 60×6000", {
                let mut t = "|a".repeat(60);
                t.push_str("|\n");
                t.push_str(&"|-".repeat(60));
                t.push_str("|\n");
                t.push_str(&format!("{}|\n", "|x".repeat(60)).repeat(6000));
                t
            }),
        ];
        for (name, md) in cases {
            let t = std::time::Instant::now();
            let out = r(&md);
            let _ = crate::styler::analyze(&md, true, Some(0));
            let el = t.elapsed();
            // The limit catches quadratic blow-ups, not exact speed: a debug build with coverage
            // instrumentation (scripts\coverage.ps1) is 10–20× slower than release.
            let limit = std::time::Duration::from_secs(if cfg!(debug_assertions) { 120 } else { 10 });
            assert!(el < limit, "{name}: {el:?}");
            // RTF group balance (ignoring escaped braces)
            let mut depth: i64 = 0;
            let b = out.rtf.as_bytes();
            let mut i = 0;
            while i < b.len() {
                match b[i] {
                    b'\\' => i += 1,
                    b'{' => depth += 1,
                    b'}' => depth -= 1,
                    _ => {}
                }
                assert!(depth >= 0, "{name}: extra }}");
                i += 1;
            }
            assert_eq!(depth, 0, "{name}: unbalanced RTF");
            assert!(out.rtf.len() < 64 * 1024 * 1024, "{name}: RTF too large ({} MB)", out.rtf.len() >> 20);
            let src_total: usize = out.images.iter().map(|i| i.src.len()).sum();
            assert!(src_total <= 40 * 1024 * 1024, "{name}: image addresses take {} MB", src_total >> 20);
            let url_total: usize = out.links.iter().map(|l| l.url.len()).sum();
            assert!(url_total <= 32 * 1024 * 1024, "{name}: link addresses take {} MB", url_total >> 20);
            eprintln!("{name}: {el:?}, RTF {} KB, images {}, links {}", out.rtf.len() / 1024, out.images.len(), out.links.len());
        }
    }

