        let out = r("[inline](https://a.example/x) [ref][r] <https://auto.example> [mail](mailto:me@mail.example) www.site.example/p\n\n[r]: https://ref.example \"t\"\n");
        let urls: Vec<&str> = out.links.iter().map(|l| l.url.as_str()).collect();
